import { devError } from '../../utils/developmentDiagnostics';
import React, { useState, useEffect, useRef } from 'react';
import ReCAPTCHA from 'react-google-recaptcha';
import {
  Button,
  TextField,
  Typography,
  Paper,
  Slide,
  Dialog,
  DialogContent,
  Checkbox,
  FormControlLabel,
  IconButton,
  useMediaQuery,
  CircularProgress,
  Alert,
  Box,
} from '@mui/material';
import CloseIcon from '@mui/icons-material/Close';
import ArrowForwardIcon from '@mui/icons-material/ArrowForward';
import { useTheme } from '@mui/material/styles';
import { auth } from '../../firebase';
import { sendEmailVerification } from 'firebase/auth';
// Temporary - replace with study-guide-preview.jpg when available

import { validateEmail } from '../../utils/emailValidation';
import { getRecaptchaSiteKey, validateDisplayName } from '../../utils/signupValidation';
import { mapAuthApiErrorMessage } from '../../utils/authApiErrors';
import { completeEmailSignup } from '../../services/emailSignup';
import { ConversionEvents } from '../../utils/analytics';

import { useTranslation } from '../../hooks/useTranslation';
import { MichaelLottieIcon } from '../MichaelLottieIcon';

const RECAPTCHA_SITE_KEY = getRecaptchaSiteKey();
const DELAY = 1500;

interface BibleStudySignupProps {
  position?: 'modal' | 'inline' | 'floating';
  onSignup?: (email: string, name: string) => void;
  delay?: number; // Delay in milliseconds before showing the modal
  forceOpen?: boolean; // For testing purposes
}

const BibleStudySignup: React.FC<BibleStudySignupProps> = ({
  position = 'modal',
  onSignup,
  delay = 5000,
  forceOpen = false,
}) => {
  const [open, setOpen] = useState(false);
  const [step, setStep] = useState(1);
  const [email, setEmail] = useState('');
  const [name, setName] = useState('');
  const [password, setPassword] = useState('');
  const [emailError, setEmailError] = useState('');
  const [nameError, setNameError] = useState('');
  const [passwordError, setPasswordError] = useState('');
  const [honeypot, setHoneypot] = useState('');
  const [subscribed, setSubscribed] = useState(false);
  const [loading, setLoading] = useState(false);
  const submittingRef = useRef(false);
  const [optIn, setOptIn] = useState(true);
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'));
  const isDarkMode = theme.palette.mode === 'dark';

  const [serverError, setServerError] = useState('');
  const [captchaValue, setCaptchaValue] = useState<string | null>('[empty]');
  const [, setCaptchaExpired] = useState(false);
  const [captchaLoaded, setCaptchaLoaded] = useState(false);
  const { t } = useTranslation();

  const recaptchaRef = useRef<ReCAPTCHA>(null);

  useEffect(() => {
    const timer = setTimeout(() => {
      setCaptchaLoaded(true);
    }, DELAY);
    return () => clearTimeout(timer);
  }, []);

  // Show modal after delay if it's a modal
  useEffect(() => {
    if (position === 'modal' && !localStorage.getItem('leadMagnetShown')) {
      const timer = setTimeout(() => {
        setOpen(true);
      }, delay);
      return () => clearTimeout(timer);
    }
  }, [position, delay, subscribed]);

  // For testing purposes
  useEffect(() => {
    if (forceOpen && position === 'modal') {
      setOpen(true);
    }
  }, [forceOpen, position]);

  const handleOpen = () => {
    setOpen(true);
  };

  const handleClose = () => {
    setOpen(false);
    // Remember that we've shown the lead magnet and mark as dismissed
    localStorage.setItem('leadMagnetShown', 'true');

    // If user has subscribed, let's not show the popup again in the future
    if (subscribed) {
      localStorage.setItem('leadMagnetSubscribed', 'true');
    }
  };

  const handleNext = () => {
    const emailValidation = validateEmail(email);
    if (!emailValidation.isValid) {
      setEmailError(emailValidation.error || String(t('signup.pleaseEnterValidEmail')));
      return;
    }
    setEmailError('');
    setStep(2);
  };

  const validatePassword = (password: string) => {
    // Basic password validation: at least 8 characters
    return password.length >= 8;
  };

  const handleCaptchaChange = (value: string | null) => {
    setCaptchaValue(value);
    if (value === null) {
      setCaptchaExpired(true);
    } else {
      setCaptchaExpired(false);
    }
  };

  const handleSubmit = async (e: any) => {
    e.preventDefault();
    if (submittingRef.current) {
      return;
    }

    if (honeypot.trim() !== '') {
      return;
    }

    // Ensure reCAPTCHA is loaded
    if (!RECAPTCHA_SITE_KEY) {
      setServerError(
        process.env.NODE_ENV === 'development'
          ? 'reCAPTCHA is not configured. Add REACT_APP_RECAPTCHA_SITE_KEY to .env and restart the dev server.'
          : String(t('signup.captchaNotConfigured')),
      );
      return;
    }

    if (!captchaValue || captchaValue === '[empty]') {
      alert(String(t('signup.pleaseCompleteCaptcha')));
      return;
    }

    const nameValidation = validateDisplayName(name);
    if (!nameValidation.isValid) {
      setNameError(nameValidation.error ?? String(t('signup.pleaseEnterValidName')));
      return;
    }

    setNameError('');

    // Validate email domain again in case user changed it
    const emailValidation = validateEmail(email);
    if (!emailValidation.isValid) {
      setEmailError(emailValidation.error || String(t('signup.pleaseEnterValidEmail')));
      return;
    }

    if (!validatePassword(password)) {
      setPasswordError(String(t('signup.passwordMinLength')));
      return;
    }

    setPasswordError('');
    setEmailError('');

    submittingRef.current = true;
    setLoading(true);
    setServerError('');

    try {
      const { user } = await completeEmailSignup(auth, {
        email,
        password,
        displayName: name,
        firstName: name,
        source: 'bible-study-signup',
        recaptchaToken: captchaValue,
        optIn,
      });
      // Send only after provisioning succeeds, including a recovered signup.
      // Delivery failure must not turn a completed account into a failed signup.
      if (!user.emailVerified) {
        try {
          await sendEmailVerification(user);
        } catch {
          setServerError('Your account is ready, but the verification email could not be sent.');
        }
      }

      setSubscribed(true);
      ConversionEvents.signUpComplete('email', 'scroll-signup');

      // Call the onSignup prop if provided
      if (onSignup) {
        onSignup(email, name);
      }

      localStorage.setItem('leadMagnetSubscribed', 'true');

      window.dispatchEvent(new CustomEvent('accountSignupComplete'));

      // After 3 seconds, close the modal
      setTimeout(() => {
        handleClose();
      }, 3000);
    } catch (error) {
      devError('Error subscribing.');
      setServerError(mapAuthApiErrorMessage(error, String(t('signup.failedToSubscribe'))));
    } finally {
      submittingRef.current = false;
      recaptchaRef.current?.reset();
      setCaptchaValue(null);
      setLoading(false);
    }
  };

  const renderContent = () => {
    if (subscribed) {
      return (
        <div style={{ textAlign: 'center', padding: '1rem' }}>
          {serverError && <Alert severity="warning">{serverError}</Alert>}
          <Typography variant="h5" gutterBottom>
            {String(t('signup.thankYouForSubscribing'))}
          </Typography>
          <Typography variant="body1" paragraph></Typography>
          <Typography variant="body2" color="text.secondary">
            {String(t('signup.closeWindowMessage'))}
          </Typography>
        </div>
      );
    }

    return (
      <>
        {step === 1 ? (
          <>
            <div
              style={{
                display: 'flex',
                flexDirection: 'column',
                alignItems: 'center',
                marginBottom: '1rem',
                placeSelf: 'center',
                textAlign: 'center',
              }}
            >
              <MichaelLottieIcon size={160} sx={{ mb: 1.5 }} />
              <Typography variant="h6" component="h2">
                {String(t('signup.createFreeAccount'))}
              </Typography>
            </div>
            <Typography variant="body2" paragraph sx={{ fontWeight: 500 }}>
              {String(t('signup.unlockDeeperUnderstanding'))}
            </Typography>
            <Typography variant="body2" paragraph sx={{ fontWeight: 500 }}>
              {String(t('signup.stayReadyStayCovered'))}
            </Typography>
            <div
              style={{
                display: 'flex',
                flexDirection: isMobile ? 'column' : 'row',
                gap: '1rem',
                marginBottom: '0rem',
              }}
            >
              {/* 
              <div style={{ flex: 1, minWidth: isMobile ? '100%' : '45%' }}>
                <Typography variant="body2" paragraph>
                  Our Bible study guide includes:
                </Typography>
                <ul style={{ listStyleType: 'none', paddingLeft: 0, marginBottom: '1rem' }}>
                  <li style={{ display: 'flex', alignItems: 'center', marginBottom: '0.5rem' }}>
                    <CheckCircle sx={{ width: 20, height: 20 }} color="success" />
                    <Typography variant="body2" style={{ fontSize: 15, marginLeft: '0.5rem' }}>Daily devotionals</Typography>
                  </li>
                  <li style={{ display: 'flex', alignItems: 'center', marginBottom: '0.5rem' }}>
                    <CheckCircle sx={{ width: 20, height: 20 }} color="success" />
                    <Typography variant="body2" style={{ fontSize: 15, marginLeft: '0.5rem' }}>Verse commentary</Typography>
                  </li>
                  <li style={{ display: 'flex', alignItems: 'center', marginBottom: '0.5rem' }}>
                    <CheckCircle sx={{ width: 20, height: 20 }} color="success" />
                    <Typography variant="body2" style={{ fontSize: 15, marginLeft: '0.5rem' }}>Historical context</Typography>
                  </li>
                  <li style={{ display: 'flex', alignItems: 'center', marginBottom: '0.5rem' }}>
                    <CheckCircle sx={{ width: 20, height: 20 }} color="success" />
                    <Typography variant="body2" style={{ fontSize: 15, marginLeft: '0.5rem' }}>Reflection questions</Typography>
                  </li>
                </ul>
                <Typography variant="body2" paragraph sx={{ fontStyle: 'italic' }}>
                  "This study guide transformed my daily devotional time!" - Sarah K.
                </Typography>
              </div> */}
              {/* {!isMobile && (
                <div
                  style={{
                    flex: 1,
                    display: "flex",
                    justifyContent: "center",
                    alignItems: "center",
                    borderRadius: 1,
                    overflow: "hidden",
                  }}
                >
                  <img
                    src={studyGuideImage}
                    alt="Bible Study Guide Preview"
                    style={{
                      maxWidth: "100%",
                      maxHeight: 180,
                      objectFit: "cover",
                      borderRadius: 1,
                    }}
                  />
                </div>
              )} */}
            </div>
            <TextField
              fullWidth
              label={String(t('signup.emailAddress'))}
              variant="outlined"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              error={!!emailError}
              helperText={emailError}
              margin="normal"
              autoFocus
              sx={{ mb: 4 }}
            />
            <Button
              fullWidth
              variant="contained"
              color="primary"
              size="large"
              onClick={handleNext}
              endIcon={<ArrowForwardIcon />}
              sx={{ mb: 2 }}
            >
              {String(t('signup.signUp'))}
            </Button>
            <Typography variant="caption" color="text.secondary" align="center" display="block">
              {String(t('signup.privacyMessage'))}
            </Typography>
            <Typography variant="caption" color="text.secondary" align="center" display="block">
              {/* {String(t("signup.dontWantToSignUp"))} */}
            </Typography>
          </>
        ) : (
          <>
            <div
              style={{
                display: 'flex',
                flexDirection: 'column',
                alignItems: 'center',
                marginBottom: '1rem',
                placeSelf: 'center',
              }}
            >
              <Typography variant="h6" component="h2" gutterBottom>
                {String(t('signup.almostThere'))}
              </Typography>
              <Typography variant="body2" paragraph>
                {String(t('signup.enterNameAndPassword'))}
              </Typography>
              <TextField
                fullWidth
                label={String(t('signup.yourName'))}
                variant="outlined"
                value={name}
                onChange={(e) => {
                  setName(e.target.value);
                  if (nameError) {
                    setNameError('');
                  }
                }}
                error={!!nameError}
                helperText={nameError}
                margin="normal"
                autoFocus
                sx={{ mb: 2 }}
              />
              <TextField
                fullWidth
                label={String(t('signup.createPassword'))}
                variant="outlined"
                type="password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                error={!!passwordError}
                helperText={passwordError}
                margin="normal"
                sx={{ mb: 2 }}
              />
              <FormControlLabel
                control={
                  <Checkbox
                    checked={optIn}
                    onChange={(e) => setOptIn(e.target.checked)}
                    color="primary"
                  />
                }
                label={String(t('signup.receiveMonthlyNews'))}
                sx={{ mb: 2 }}
              />
              {captchaLoaded && RECAPTCHA_SITE_KEY && (
                <Box sx={{ my: 2, placeSelf: 'center' }}>
                  <ReCAPTCHA
                    ref={recaptchaRef}
                    sitekey={RECAPTCHA_SITE_KEY}
                    onChange={handleCaptchaChange}
                  />
                </Box>
              )}
              <Box
                component="input"
                type="text"
                name="company"
                tabIndex={-1}
                autoComplete="off"
                aria-hidden="true"
                value={honeypot}
                onChange={(event) => setHoneypot(event.target.value)}
                sx={{
                  position: 'absolute',
                  left: '-9999px',
                  width: 1,
                  height: 1,
                  opacity: 0,
                  pointerEvents: 'none',
                }}
              />

              {serverError && (
                <Alert severity="error" sx={{ mb: 2 }}>
                  {serverError}
                </Alert>
              )}
              <Button
                fullWidth
                variant="contained"
                color="primary"
                size="large"
                onClick={handleSubmit}
                disabled={loading}
                sx={{ mb: 2 }}
              >
                {loading ? <CircularProgress size={24} /> : String(t('signup.createAccount'))}
              </Button>
              <Button fullWidth variant="text" onClick={() => setStep(1)} sx={{ mb: 1 }}>
                {String(t('signup.back'))}
              </Button>
            </div>
          </>
        )}
      </>
    );
  };

  // For modal position
  if (position === 'modal') {
    return (
      <Dialog
        open={open}
        onClose={loading ? undefined : handleClose}
        maxWidth="sm"
        fullWidth
        PaperProps={{
          elevation: 5,
          sx: {
            overflow: 'hidden',
          },
        }}
      >
        <div
          style={{
            position: 'absolute',
            right: 8,
            top: 8,
            color: '#a1a1a1',
            zIndex: 1,
          }}
        >
          <IconButton onClick={handleClose} disabled={loading}>
            <CloseIcon />
          </IconButton>
        </div>
        <DialogContent sx={{ p: { xs: 2, sm: 3 }, mt: 1 }}>{renderContent()}</DialogContent>
      </Dialog>
    );
  }

  // For inline position
  if (position === 'inline') {
    return (
      <Paper
        elevation={3}
        sx={{
          p: 3,
          mb: 4,
          borderRadius: 2,
          bgcolor: isDarkMode ? 'rgba(33, 33, 33, 0.9)' : 'rgba(255, 255, 255, 0.9)',
        }}
      >
        {renderContent()}
      </Paper>
    );
  }

  // For floating position
  return (
    <Slide
      direction="down"
      in={
        (!localStorage.getItem('leadMagnetShown') &&
          !localStorage.getItem('leadMagnetSubscribed')) ||
        forceOpen
      }
    >
      <Paper
        elevation={4}
        sx={{
          position: 'fixed',
          top: 0,
          left: 0,
          right: 0,
          zIndex: 1300,
          p: 2,
          bgcolor: isDarkMode ? 'rgba(33, 33, 33, 0.95)' : 'rgba(255, 255, 255, 0.95)',
          boxShadow: 3,
          borderBottomLeftRadius: 2,
          borderBottomRightRadius: 2,
        }}
      >
        <div
          style={{
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'space-between',
            maxWidth: 1200,
          }}
        >
          <MichaelLottieIcon size={120} sx={{ mr: 1 }} />
          <div style={{ display: 'flex', alignItems: 'center', flex: 1 }}>
            <Typography variant="body1" sx={{ fontWeight: 500, mr: 2 }}></Typography>
          </div>
          <div style={{ display: 'flex', alignItems: 'center', gap: 1 }}>
            <Button variant="contained" color="primary" size="small" onClick={handleOpen}>
              {String(t('signup.getFreeAccess'))}
            </Button>
            <IconButton size="small" onClick={handleClose}>
              <CloseIcon fontSize="small" />
            </IconButton>
          </div>
        </div>
      </Paper>
    </Slide>
  );
};

export default BibleStudySignup;
