import Box from '@mui/material/Box';
import MenuItem from '@mui/material/MenuItem';
import Select, { SelectChangeEvent } from '@mui/material/Select';
import Table from '@mui/material/Table';
import TableBody from '@mui/material/TableBody';
import TableCell from '@mui/material/TableCell';
import TableContainer from '@mui/material/TableContainer';
import TableHead from '@mui/material/TableHead';
import TableRow from '@mui/material/TableRow';
import Typography from '@mui/material/Typography';

import { translateBookName } from '../../utils/bookTranslations';
import { cleanVerseText } from '../../utils/misc';

export interface PhraseSearchVerse {
  readonly book: string;
  readonly chapter: number;
  readonly verse: number;
  readonly text: string;
  readonly id: string;
}

interface PhraseSearchResultsProps {
  readonly results: readonly PhraseSearchVerse[];
  readonly totalCount: number;
  readonly resultsPerPage: number;
  readonly onResultsPerPageChange: (event: SelectChangeEvent<number>) => void;
  readonly translation: string;
  readonly t: (key: string, options?: unknown) => string | object;
  readonly referenceLabel: string;
  readonly textLabel: string;
  readonly resultsLabel: string;
  readonly perPageLabel: string;
  readonly onRowHover: (
    event: React.MouseEvent<HTMLElement>,
    verse: Pick<PhraseSearchVerse, 'book' | 'chapter' | 'verse'>,
  ) => void;
}

export function PhraseSearchResults({
  results,
  totalCount,
  resultsPerPage,
  onResultsPerPageChange,
  translation,
  t,
  referenceLabel,
  textLabel,
  resultsLabel,
  perPageLabel,
  onRowHover,
}: PhraseSearchResultsProps): JSX.Element {
  return (
    <Box className="phrase-search-results" sx={{ width: '100%' }}>
      <Box
        sx={{
          display: 'flex',
          alignItems: 'center',
          flexWrap: 'wrap',
          gap: 1.5,
          mb: 2,
          pb: 1.5,
          borderBottom: (theme) =>
            `1px solid ${
              theme.palette.mode === 'light' ? 'rgba(0, 0, 0, 0.12)' : 'rgba(255, 255, 255, 0.12)'
            }`,
        }}
      >
        <Typography
          variant="body2"
          sx={{
            fontSize: '0.875rem',
            color: 'text.secondary',
            letterSpacing: '0.02em',
          }}
        >
          {totalCount.toLocaleString()} {resultsLabel}
        </Typography>
        <Select
          value={resultsPerPage}
          onChange={onResultsPerPageChange}
          size="small"
          sx={{ minWidth: 72, height: '2rem', fontSize: '0.875rem' }}
        >
          <MenuItem value={10}>10</MenuItem>
          <MenuItem value={25}>25</MenuItem>
          <MenuItem value={50}>50</MenuItem>
          <MenuItem value={100}>100</MenuItem>
        </Select>
        <Typography variant="caption" sx={{ color: 'text.secondary' }}>
          {perPageLabel}
        </Typography>
      </Box>

      <TableContainer
        component={Box}
        sx={{
          width: '100%',
          overflowX: 'auto',
        }}
      >
        <Table
          className="phrase-search-table"
          size="small"
          aria-label={resultsLabel}
          sx={{
            width: '100%',
            borderCollapse: 'collapse',
            '& .MuiTableCell-root': {
              borderBottom: (theme) =>
                `1px solid ${
                  theme.palette.mode === 'light'
                    ? 'rgba(0, 0, 0, 0.08)'
                    : 'rgba(255, 255, 255, 0.08)'
                }`,
              py: 1.25,
              px: { xs: 1, sm: 1.5 },
              verticalAlign: 'top',
              fontSize: 'inherit',
              lineHeight: 1.55,
            },
            '& .MuiTableHead-root .MuiTableCell-root': {
              fontWeight: 600,
              fontSize: '0.75rem',
              textTransform: 'uppercase',
              letterSpacing: '0.06em',
              color: 'text.secondary',
              borderBottom: (theme) =>
                `2px solid ${
                  theme.palette.mode === 'light'
                    ? 'rgba(0, 0, 0, 0.16)'
                    : 'rgba(255, 255, 255, 0.16)'
                }`,
              py: 1,
            },
            '& .MuiTableBody-root .MuiTableRow-root:hover': {
              backgroundColor: (theme) =>
                theme.palette.mode === 'light'
                  ? 'rgba(0, 0, 0, 0.03)'
                  : 'rgba(255, 255, 255, 0.04)',
            },
          }}
        >
          <TableHead>
            <TableRow>
              <TableCell scope="col" sx={{ width: { xs: '28%', sm: '22%' }, minWidth: 88 }}>
                {referenceLabel}
              </TableCell>
              <TableCell scope="col">{textLabel}</TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {results.map((row) => {
              const reference = `${translateBookName(row.book, t)} ${row.chapter}:${row.verse}`;
              const verseText = cleanVerseText(row.text, translation);

              return (
                <TableRow key={`${row.book}-${row.chapter}-${row.verse}-${row.id}`} hover>
                  <TableCell
                    component="th"
                    scope="row"
                    itemScope
                    itemType="https://schema.org/BibleVerse"
                    sx={{
                      fontWeight: 500,
                      fontVariantNumeric: 'tabular-nums',
                      whiteSpace: 'nowrap',
                      color: 'text.secondary',
                    }}
                  >
                    <meta itemProp="book" content={row.book} />
                    <meta itemProp="chapter" content={String(row.chapter)} />
                    <meta itemProp="verse" content={String(row.verse)} />
                    <Box component="cite" itemProp="position" sx={{ fontStyle: 'normal' }}>
                      {reference}
                    </Box>
                  </TableCell>
                  <TableCell
                    itemProp="text"
                    onMouseEnter={(event) =>
                      onRowHover(event, {
                        book: row.book,
                        chapter: row.chapter,
                        verse: row.verse,
                      })
                    }
                  >
                    <Box
                      component="q"
                      cite={`${row.book} ${row.chapter}:${row.verse}`}
                      sx={{ quotes: 'none' }}
                    >
                      {verseText}
                    </Box>
                  </TableCell>
                </TableRow>
              );
            })}
          </TableBody>
        </Table>
      </TableContainer>
    </Box>
  );
}
