import { devError } from '../utils/developmentDiagnostics';
import React, { useState, useEffect, useCallback } from 'react';
import { onAuthStateChanged } from 'firebase/auth';
import { verifyStripeSubscription } from '../services/stripe';
import { auth } from '../firebase';

// Define the shape of our subscription state
interface SubscriptionState {
  isActive: boolean;
  plan: string | null;
  expiresAt: string | null;
  subscriptionId: string | null;
  status?: string | null; // For tracking trial status
}

// Define the shape of our context
interface SubscriptionContextType {
  subscription: SubscriptionState;
  refreshStatus: () => Promise<void>;
  canUseComments: boolean;
  clearSubscriptionData: () => void;
}

// Create the context with default values
const SubscriptionContext = React.createContext<SubscriptionContextType>({
  subscription: {
    isActive: false,
    plan: null,
    expiresAt: null,
    subscriptionId: null,
  },
  refreshStatus: async () => {
    /* No provider is mounted. */
  },
  canUseComments: false,
  clearSubscriptionData: () => {
    /* No provider is mounted. */
  },
});

// Custom hook to use the context
export const useSubscription = () => {
  const context = React.useContext(SubscriptionContext);
  if (context === undefined) {
    throw new Error('useSubscription must be used within a SubscriptionProvider');
  }
  return context;
};

// Provider component
export const SubscriptionProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [subscription, setSubscription] = useState<SubscriptionState>({
    isActive: false,
    plan: null,
    expiresAt: null,
    subscriptionId: null,
  });
  const [userEmail, setUserEmail] = useState<string | null>(() =>
    localStorage.getItem('userEmail'),
  );
  const [isAuthenticated, setIsAuthenticated] = useState(false);

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, (currentUser) => {
      setIsAuthenticated(Boolean(currentUser));
      const email = currentUser?.email ?? localStorage.getItem('userEmail');
      setUserEmail(email);
      if (currentUser?.email) {
        localStorage.setItem('userEmail', currentUser.email);
      }
    });
    return () => unsubscribe();
  }, []);

  // Function to clear all subscription data and redirect to login
  const clearSubscriptionData = () => {
    // Clear all subscription-related data from localStorage
    const userEmail = localStorage.getItem('userEmail');
    if (userEmail) {
      const storageKey = `subscription_${userEmail.replace(/[^a-zA-Z0-9]/g, '_').toLowerCase()}`;
      localStorage.removeItem(storageKey);
    }
    localStorage.removeItem('user_subscription');
    // localStorage.removeItem('userEmail');
    localStorage.removeItem('is_test_subscription');

    // Clear cookies
    // Cookies.remove('wpToken');
    // Cookies.remove('userId');

    // Reset subscription state
    setSubscription({
      isActive: false,
      plan: null,
      expiresAt: null,
      subscriptionId: null,
    });

    // Redirect to login page
    // navigate('/login');
  };

  const refreshStatus = useCallback(async () => {
    if (!userEmail) {
      setSubscription({
        isActive: false,
        plan: null,
        expiresAt: null,
        subscriptionId: null,
      });
      return;
    }

    try {
      const status = await verifyStripeSubscription(userEmail);

      setSubscription(status);
    } catch (error) {
      devError('Error refreshing subscription status.');
      setSubscription({
        isActive: false,
        plan: null,
        expiresAt: null,
        subscriptionId: null,
      });
    }
  }, [userEmail]);

  useEffect(() => {
    void refreshStatus();
  }, [refreshStatus]); // Run only when userEmail changes

  // Logged-in users can comment; subscription is not required (see SubscriptionCheck).
  const canUseComments = isAuthenticated;

  const value = {
    subscription,
    refreshStatus,
    canUseComments,
    clearSubscriptionData,
  };

  return <SubscriptionContext.Provider value={value}>{children}</SubscriptionContext.Provider>;
};

export default SubscriptionContext;
