import React, { lazy, Suspense } from 'react';

import { Box, type SxProps, type Theme } from '@mui/material';
import { useTheme } from '@mui/material/styles';

const MichaelLottie = lazy(async () => {
  const [{ DotLottieReact }, animationModule] = await Promise.all([
    import('@lottiefiles/dotlottie-react'),
    import('../assets/animations/michael.json'),
  ]);
  const michaelData = JSON.stringify(animationModule.default);
  const Component: React.FC = () => {
    return (
      <DotLottieReact data={michaelData} loop autoplay style={{ width: '100%', height: '100%' }} />
    );
  };
  return { default: Component };
});

export interface MichaelLottieIconProps {
  /** Container size in px (width and height). Default 40 for compact inline use. */
  readonly size?: number;
  readonly sx?: SxProps<Theme>;
}

/** Renders the asset as white in dark mode and black in light mode (works best for single-color artwork). */
const themeLottieFilter = (mode: 'light' | 'dark'): string => {
  return mode === 'dark' ? 'brightness(0) invert(1)' : 'brightness(0)';
};

export const MichaelLottieIcon: React.FC<MichaelLottieIconProps> = ({ size = 28, sx }) => {
  const theme = useTheme();
  const mode = theme.palette.mode;

  return (
    <Box
      sx={{
        width: size,
        height: size,
        flexShrink: 0,
        display: 'inline-flex',
        alignItems: 'center',
        justifyContent: 'center',
        filter: themeLottieFilter(mode),
        WebkitFilter: themeLottieFilter(mode),
        ...sx,
      }}
    >
      <Suspense fallback={<Box sx={{ width: size, height: size }} />}>
        <MichaelLottie />
      </Suspense>
    </Box>
  );
};
