import { devError } from '../../../utils/developmentDiagnostics';
import React, { useEffect, useState, useMemo } from 'react';
import { Box, Typography, Avatar, Collapse } from '@mui/material';
import FavoriteIcon from '@mui/icons-material/Favorite';
import ReplyIcon from '@mui/icons-material/Reply';
import ExpandMoreIcon from '@mui/icons-material/ExpandMore';
import ExpandLessIcon from '@mui/icons-material/ExpandLess';
import Cookies from 'js-cookie';
import { User } from 'firebase/auth';
import Reply from './Reply';
import { useTranslation } from '../../../hooks/useTranslation';

interface CommentProps {
  comment: any;
  user: User | null;
  replies?: any[];
  postID: number | null;
  onReplySubmitted?: () => void;
  onReplyClick?: (parentId: number, username: string) => void;
}

// Function to process @ mentions in the content
const processMentions = (content: string) => {
  if (!content) {
    return content;
  }

  // Pattern to match @username mentions (alphanumeric, underscore, dot)
  const mentionPattern = /@(\w+(?:\.\w+)?)/g;

  return content.replace(mentionPattern, (match, username) => {
    return `<span style="color: #1976d2; font-weight: 500; cursor: pointer;" onclick="alert('User: ${username}')">@${username}</span>`;
  });
};

const Comment: React.FC<CommentProps> = ({ comment, user, replies = [], onReplyClick }) => {
  const { t } = useTranslation();

  const [likes, setLikes] = useState(comment.likes || 0);
  const [liked, setLiked] = useState(false);
  const [showReplies, setShowReplies] = useState(false);
  const [repliesList, setRepliesList] = useState(replies);
  const [, setPendingReplies] = useState<any[]>([]); // Store locally added replies that haven't been confirmed by API yet
  const userId = Cookies.get('userId');
  const wpToken = Cookies.get('wpToken');

  const handleLike = async () => {
    const action = liked ? 'unlike' : 'like';
    try {
      const response = await fetch(
        `${process.env.REACT_APP_WP_API_URL_CUSTOM}/like-comment/${comment?.id}`,
        {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            Authorization: `Basic ${btoa(`${user?.email || ''}:${wpToken}`)}`,
          },
          body: JSON.stringify({ action }),
        },
      );
      const data = await response.json();
      setLikes(data.likes);
      setLiked(!liked);
    } catch (error) {
      devError('Error liking comment.');
    }
  };

  const likedUserData = comment?.liked_users;

  const likedUsers = useMemo(
    () => (likedUserData ? Object.values(likedUserData) : []),
    [likedUserData],
  );

  useEffect(() => {
    if (userId && likedUsers.includes(parseInt(userId))) {
      setLiked(true);
    }
  }, [comment.likes, userId, likedUsers]);

  useEffect(() => {
    // Merge fetched replies with any pending (locally added) replies
    // This ensures locally added replies don't disappear while waiting for API confirmation
    setPendingReplies((currentPending) => {
      if (!replies || replies.length === 0) {
        // If no fetched replies, keep pending ones
        if (currentPending.length > 0) {
          setRepliesList(currentPending);
        }
        return currentPending;
      }

      const fetchedReplyIds = new Set(replies.map((r: any) => r.id));

      // Filter out pending replies that now exist in fetched replies (they've been confirmed by API)
      const stillPending = currentPending.filter(
        (pending: any) => !fetchedReplyIds.has(pending.id),
      );

      // Merge confirmed replies with still-pending ones (those not yet in API response)
      const mergedReplies = [...replies, ...stillPending];
      setRepliesList(mergedReplies);

      return stillPending;
    });
  }, [replies]);

  const processedContent = comment?.content?.rendered
    ? processMentions(comment.content.rendered)
    : '';

  const replyCount = repliesList.length;

  return (
    <Box
      sx={{
        mb: 0.5,
        p: 1.5,
        borderRadius: 1.5,
        backgroundColor: (theme) =>
          theme.palette.mode === 'dark' ? 'rgba(255, 255, 255, 0.03)' : 'rgba(0, 0, 0, 0.02)',
        border: (theme) =>
          `0px solid ${theme.palette.mode === 'dark' ? 'rgba(255, 255, 255, 0.06)' : 'rgba(0, 0, 0, 0.06)'}`,
        transition: 'all 0.2s ease-in-out',
        '&:hover': {
          backgroundColor: (theme) =>
            theme.palette.mode === 'dark' ? 'rgba(255, 255, 255, 0.05)' : 'rgba(0, 0, 0, 0.03)',
          borderColor: (theme) =>
            theme.palette.mode === 'dark' ? 'rgba(255, 255, 255, 0.1)' : 'rgba(0, 0, 0, 0.1)',
        },
      }}
    >
      <Box
        sx={{
          display: 'flex',
          alignItems: 'flex-start',
        }}
      >
        <Avatar
          alt={comment.author_name}
          src={comment.author_avatar_urls?.[48]}
          sx={{
            mr: 1,
            width: '15px',
            height: '15px',
            borderRadius: '0%',
          }}
        />
        <Box sx={{ flex: 1 }}>
          <Typography
            variant="body2"
            sx={{
              fontWeight: 600,
              color: (theme) =>
                theme.palette.mode === 'dark' ? 'rgba(255, 255, 255, 0.9)' : 'rgba(0, 0, 0, 0.9)',
              fontSize: '0.5rem',
              mb: 0,
            }}
          >
            {comment.author_name}
          </Typography>
          <Typography
            variant="body2"
            sx={{
              px: 0,
              mt: 0.25,
              lineHeight: 1,
              fontSize: '0.65rem',
              color: (theme) =>
                theme.palette.mode === 'dark' ? 'rgba(255, 255, 255, 0.8)' : 'rgba(0, 0, 0, 0.8)',
              wordBreak: 'break-word',
              whiteSpace: 'pre-wrap',
              overflowWrap: 'break-word',
              textAlign: 'left',
              fontFamily: "'Alegreya Sans', sans-serif",
              '& a': {
                color: (theme) =>
                  theme.palette.mode === 'dark' ? 'rgba(173, 216, 230, 0.9)' : '#1976d2',
                textDecoration: 'underline',
                transition: 'color 0.2s ease',
                '&:hover': {
                  color: (theme) =>
                    theme.palette.mode === 'dark' ? 'rgba(173, 216, 230, 1)' : '#1565c0',
                },
              },
            }}
            dangerouslySetInnerHTML={{ __html: processedContent }}
          />
          <Box sx={{ display: 'flex', alignItems: 'center', mt: -1.75, gap: 1 }}>
            <Box
              sx={{
                display: 'flex',
                alignItems: 'center',
                gap: 0.5,
                px: 1,
                py: 0,
                borderRadius: 1.5,
                transition: 'all 0.2s ease-in-out',
                cursor: 'pointer',
                '&:hover': {
                  backgroundColor: (theme) =>
                    theme.palette.mode === 'dark'
                      ? 'rgba(255, 255, 255, 0.05)'
                      : 'rgba(0, 0, 0, 0.05)',
                },
              }}
              onClick={handleLike}
            >
              <FavoriteIcon
                sx={{
                  color:
                    liked || likedUsers.includes(parseInt(userId ? userId : '0'))
                      ? (theme) => theme.palette.warning.main
                      : (theme) =>
                          theme.palette.mode === 'dark'
                            ? 'rgba(255, 255, 255, 0.5)'
                            : 'rgba(0, 0, 0, 0.5)',
                  width: '15px',
                  height: '15px',
                  transition: 'all 0.2s ease-in-out',
                }}
              />
              <Typography
                variant="body2"
                sx={{
                  color: (theme) =>
                    theme.palette.mode === 'dark'
                      ? 'rgba(255, 255, 255, 0.7)'
                      : 'rgba(0, 0, 0, 0.7)',
                  fontSize: '0.65rem',
                  fontWeight: 500,
                  fontFamily: "'Alegreya Sans', sans-serif",
                }}
              >
                {likes}
              </Typography>
            </Box>

            {/* Show/hide replies button - visible to everyone */}
            {replyCount > 0 && (
              <Box
                sx={{
                  display: 'flex',
                  alignItems: 'center',
                  gap: 0.5,
                  px: 1,
                  py: 0.5,
                  borderRadius: 1.5,
                  transition: 'all 0.2s ease-in-out',
                  cursor: 'pointer',
                  '&:hover': {
                    backgroundColor: (theme) =>
                      theme.palette.mode === 'dark'
                        ? 'rgba(255, 255, 255, 0.05)'
                        : 'rgba(0, 0, 0, 0.05)',
                  },
                }}
                onClick={() => setShowReplies(!showReplies)}
              >
                {showReplies ? (
                  <ExpandLessIcon
                    sx={{
                      width: '15px',
                      height: '15px',
                      color: (theme) =>
                        theme.palette.mode === 'dark'
                          ? 'rgba(255, 255, 255, 0.7)'
                          : 'rgba(0, 0, 0, 0.7)',
                    }}
                  />
                ) : (
                  <ExpandMoreIcon
                    sx={{
                      width: '15px',
                      height: '15px',
                      color: (theme) =>
                        theme.palette.mode === 'dark'
                          ? 'rgba(255, 255, 255, 0.7)'
                          : 'rgba(0, 0, 0, 0.7)',
                    }}
                  />
                )}
                <Typography
                  variant="body2"
                  sx={{
                    color: (theme) =>
                      theme.palette.mode === 'dark'
                        ? 'rgba(255, 255, 255, 0.7)'
                        : 'rgba(0, 0, 0, 0.7)',
                    fontSize: '0.65rem',
                    fontWeight: 500,
                    fontFamily: "'Alegreya Sans', sans-serif",
                  }}
                >
                  {replyCount}{' '}
                  {replyCount === 1
                    ? String(t('comments.replySingular'))
                    : String(t('comments.replies'))}
                </Typography>
              </Box>
            )}

            {/* Reply button - only visible when logged in */}
            {user && (
              <Box
                sx={{
                  display: 'flex',
                  alignItems: 'center',
                  gap: 0.5,
                  px: 1,
                  py: 0.5,
                  borderRadius: 1.5,
                  transition: 'all 0.2s ease-in-out',
                  cursor: 'pointer',
                  '&:hover': {
                    backgroundColor: (theme) =>
                      theme.palette.mode === 'dark'
                        ? 'rgba(255, 255, 255, 0.05)'
                        : 'rgba(0, 0, 0, 0.05)',
                  },
                }}
                onClick={() => {
                  if (onReplyClick) {
                    onReplyClick(comment.id, comment.author_name || 'Unknown');
                  }
                }}
              >
                <ReplyIcon
                  sx={{
                    width: '15px',
                    height: '15px',
                    color: (theme) =>
                      theme.palette.mode === 'dark'
                        ? 'rgba(255, 255, 255, 0.7)'
                        : 'rgba(0, 0, 0, 0.7)',
                  }}
                />
                <Typography
                  variant="body2"
                  sx={{
                    color: (theme) =>
                      theme.palette.mode === 'dark'
                        ? 'rgba(255, 255, 255, 0.7)'
                        : 'rgba(0, 0, 0, 0.7)',
                    fontSize: '0.60rem',
                    fontWeight: 500,
                    fontFamily: "'Alegreya Sans', sans-serif",
                  }}
                >
                  Add Reply
                </Typography>
              </Box>
            )}
          </Box>
        </Box>
      </Box>

      {/* Replies */}
      {replyCount > 0 && (
        <Collapse in={showReplies}>
          <Box sx={{ mt: 1 }}>
            {repliesList.map((reply) => (
              <Reply key={reply.id} reply={reply} user={user} onReplyClick={onReplyClick} />
            ))}
          </Box>
        </Collapse>
      )}
    </Box>
  );
};

export default Comment;
