import { useState, useEffect } from 'react';
import { Box } from '@mui/material';
import Tooltip from '@mui/material/Tooltip';
import Cookies from 'js-cookie';
import IconButton from '@mui/material/IconButton';
import BookmarkAddIcon from '@mui/icons-material/BookmarkAdd'; // New bookmark icon
import BookmarkRemoveIcon from '@mui/icons-material/BookmarkRemove'; // Remove bookmark icon
import { useTranslation } from '../../hooks/useTranslation';
import { translateBookName } from '../../utils/bookTranslations';

interface BookmarkProps {
  verse: { book: string; chapter?: number | string }[];
  page: number;
  fetchVerse: (
    book: string,
    chapter: number,
    search: string,
    setData: (data: { book: string }[]) => void,
    setVerse: (verse: number) => void,
    translation: string,
  ) => void;
  setSearch: (search: string) => void;
  setData: (data: { book: string }[]) => void;
  setVerse: (verse: number) => void;
  setPage: (page: number) => void;
}

function Bookmark({
  verse,
  page,
  fetchVerse,
  setSearch,
  setData,
  setVerse,
  setPage,
}: BookmarkProps) {
  const { t } = useTranslation();
  const [bookmark, setBookmark] = useState<{ book: string; chapter: number } | null>(null);

  useEffect(() => {
    // Load bookmark from cookies on component mount
    const savedBookmark = Cookies.get('bookmark');
    if (savedBookmark) {
      setBookmark(JSON.parse(savedBookmark));
    }
  }, []);

  // Handle adding/removing the bookmark
  const handleToggleBookmark = () => {
    if (bookmark) {
      // If there's a bookmark, remove it
      setBookmark(null);
      Cookies.remove('bookmark');
      // Dispatch custom event to notify other components
      window.dispatchEvent(new CustomEvent('bookmarkChanged'));
    } else if (verse.length > 0) {
      // If no bookmark, add one — use verse chapter (displayed content), not stale page state
      const chapter =
        verse[0]?.chapter !== null && verse[0]?.chapter !== undefined
          ? Number(verse[0].chapter)
          : page;
      const newBookmark = { book: verse[0]?.book, chapter };
      setBookmark(newBookmark);
      Cookies.set('bookmark', JSON.stringify(newBookmark), { expires: 365 });
      // Dispatch custom event to notify other components
      window.dispatchEvent(new CustomEvent('bookmarkChanged'));
    }
  };

  const handleGoToBookmark = () => {
    if (bookmark) {
      const t = Cookies.get('translation');
      fetchVerse(bookmark.book, bookmark.chapter, '', setData, setVerse, t || 'kjv');
      setSearch(bookmark.book);
      setPage(bookmark.chapter);
      setVerse(1);
    }
  };

  return (
    <Box display={'flex'} sx={{ alignItems: 'center' }}>
      {/* Toggle Bookmark Icon */}
      <Tooltip
        title={bookmark ? String(t('bookmark.removeBookmark')) : String(t('bookmark.addBookmark'))}
      >
        <IconButton
          onClick={handleToggleBookmark}
          sx={{
            opacity: 0.75,
            '&.MuiIconButton-root:hover': {
              backgroundColor: 'rgba(0, 0, 0, 0.00)',
              opacity: 1,
            },
          }}
        >
          {bookmark ? (
            <BookmarkRemoveIcon fontSize={'small'} />
          ) : (
            <BookmarkAddIcon fontSize={'small'} />
          )}
        </IconButton>
      </Tooltip>
      {/* Go to Bookmark Section */}
      {bookmark && (
        <div style={{ marginTop: -2, marginLeft: 4 }}>
          <button
            style={{
              backgroundColor: '#fff',
              color: '#000',
              padding: '4px',
              borderRadius: '4px',
              border: 'none',
            }}
            onClick={handleGoToBookmark}
          >
            {String(t('bookmark.goTo'))} {translateBookName(bookmark.book, t)} {bookmark.chapter}
          </button>
        </div>
      )}
    </Box>
  );
}

export default Bookmark;
